import { sql } from 'drizzle-orm';
import { attachDatabasePool } from '@vercel/functions';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import type { PgDatabase, PgQueryResultHKT } from 'drizzle-orm/pg-core';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import pg from 'pg';
import { env } from '../config/env.js';
import * as schema from './schema.js';

export type Db = PgDatabase<PgQueryResultHKT, typeof schema>;

/** SQL migrations generated by drizzle-kit (server/drizzle). Resolves from both src/ and dist/. */
export const migrationsFolder = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../drizzle');

let pool: pg.Pool | undefined;
let current: Db | undefined;

/** The app's database. Tests swap in an in-memory Postgres with setDb. */
export function db(): Db {
  if (!current) throw new Error('Database is not connected. Call connectDB() first.');
  return current;
}

export function setDb(next: Db | undefined) {
  current = next;
}

/**
 * Connects to Postgres (Neon) with a connection pool over Neon's pooled DATABASE_URL; migrations use the
 * direct URL. A long-running server applies pending migrations here at startup. On Vercel they run once in
 * the build instead (see src/migrate.ts), since many function instances can start at the same time.
 */
export async function connectDB({ migrate: runPending = true }: { migrate?: boolean } = {}) {
  if (!env.databaseUrl) throw new Error('DATABASE_URL is not set (run `neon deploy` or see server/.env.example)');
  if (runPending) await withRetry(runMigrations);

  const onVercel = Boolean(process.env.VERCEL);
  pool = new pg.Pool({ connectionString: strictSsl(env.databaseUrl), max: onVercel ? 5 : 10, idleTimeoutMillis: 30_000 });
  // An idle client can be dropped when Neon scales to zero; log it instead of crashing the process.
  pool.on('error', (err) => console.error('Postgres pool error:', err.message));
  // Lets Vercel close idle connections before a function instance is suspended, so none leak.
  if (onVercel) attachDatabasePool(pool);
  setDb(drizzle(pool, { schema }));
  await withRetry(() => db().execute(sql`select 1`));
}

/**
 * Neon's URLs say `sslmode=require`, which node-postgres already treats as `verify-full` (certificate and
 * host checked) but warns will change meaning in pg v9. Spelling out verify-full keeps today's behaviour
 * and silences the warning.
 */
const strictSsl = (url: string) => url.replace(/([?&])sslmode=(prefer|require|verify-ca)\b/, '$1sslmode=verify-full');

// Network blips worth retrying at startup: a DNS lookup that fails once, or a connection cut while Neon wakes up.
const TRANSIENT = new Set(['ENOTFOUND', 'EAI_AGAIN', 'ECONNRESET', 'ECONNREFUSED', 'ETIMEDOUT', 'EPIPE']);

async function withRetry<T>(task: () => Promise<T>, attempts = 5): Promise<T> {
  for (let attempt = 1; ; attempt += 1) {
    try {
      return await task();
    } catch (err) {
      const code = (err as { code?: string; cause?: { code?: string } }).code ?? (err as { cause?: { code?: string } }).cause?.code;
      if (attempt >= attempts || !code || !TRANSIENT.has(code)) throw err;
      const delay = 1000 * 2 ** (attempt - 1);
      console.warn(`Database not reachable (${code}), retrying in ${delay / 1000}s (attempt ${attempt + 1} of ${attempts})`);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
}

/** Applies pending migrations over a direct (unpooled) connection, as Neon recommends. */
export async function runMigrations() {
  const client = new pg.Client({ connectionString: strictSsl(env.databaseUrlUnpooled || env.databaseUrl) });
  await client.connect();
  try {
    await migrate(drizzle(client), { migrationsFolder });
  } finally {
    await client.end();
  }
}

export async function disconnectDB() {
  setDb(undefined);
  await pool?.end();
  pool = undefined;
}

/**
 * For /api/health: true when a trivial query succeeds within ten seconds. Neon suspends an idle
 * database and waking it takes a few seconds, which must not look like an outage to a host's health check.
 */
export async function isDatabaseUp(): Promise<boolean> {
  if (!current) return false;
  try {
    await Promise.race([current.execute(sql`select 1`), new Promise((_, reject) => setTimeout(reject, 10_000))]);
    return true;
  } catch {
    return false;
  }
}
